  "activity_38e4781f-547f-4a3c-8513-10c2a399c5df": {
    "name": "The trouble with averages",
    "activity_type": "TYPE_DYNAMIC",
    "activity_sub_type": "SUBTYPE_DYNAMIC_PAGE",
    "content": {
      "type": "doc",
      "content": [
        {
          "type": "heading",
          "content": [
            {
              "type": "text",
              "text": "An average hides the shape"
            }
          ],
          "attrs": {
            "level": 2
          }
        },
        {
          "type": "paragraph",
          "content": [
            {
              "type": "text",
              "text": "Average order value went up. That is consistent with every customer spending a little more, and equally consistent with most customers spending less while two very large orders dragged the mean upward. Those two situations call for opposite responses."
            }
          ]
        },
        {
          "type": "bulletList",
          "content": [
            {
              "type": "listItem",
              "content": [
                {
                  "type": "paragraph",
                  "content": [
                    {
                      "type": "text",
                      "text": "The mean is pulled around by extremes. In anything money-shaped, there are always extremes."
                    }
                  ]
                }
              ]
            },
            {
              "type": "listItem",
              "content": [
                {
                  "type": "paragraph",
                  "content": [
                    {
                      "type": "text",
                      "text": "The median tells you about the typical case, which is usually what you actually wanted."
                    }
                  ]
                }
              ]
            },
            {
              "type": "listItem",
              "content": [
                {
                  "type": "paragraph",
                  "content": [
                    {
                      "type": "text",
                      "text": "If mean and median are far apart, the distribution is skewed and the average is a poor summary."
                    }
                  ]
                }
              ]
            }
          ]
        },
        {
          "type": "calloutInfo",
          "content": [
            {
              "type": "text",
              "text": "Ask for the median alongside the mean. If the person who produced the report cannot supply it, that is itself useful information about how the report was built."
            }
          ]
        },
        {
          "type": "blockQuiz",
          "attrs": {
            "quizId": "e1071664-ba0d-5e43-9ce8-13e29b9aa06d",
            "questions": [
              {
                "question_id": "2cc18a6d-796b-57b7-a69a-2b46feb6663d",
                "question": "Mean order value rose but median order value fell. What is the likely explanation?",
                "type": "multiple_choice",
                "answers": [
                  {
                    "answer_id": "e68177bc-0114-5b01-9674-3dcff1af3558",
                    "answer": "A small number of very large orders pulled the mean up",
                    "correct": true
                  },
                  {
                    "answer_id": "aa9232e8-b829-5bda-9ec1-c23e91aafc45",
                    "answer": "Most customers are spending more per order",
                    "correct": false
                  },
                  {
                    "answer_id": "4b483c72-1795-5af1-b83e-7e769e9e1689",
                    "answer": "The total number of orders increased",
                    "correct": false
                  }
                ]
              }
            ]
          }
        }
      ]
    },
    "details": null,
    "published": true,
    "lock_type": "public",
    "id": 92,
    "org_id": 2,
    "course_id": 23,
    "activity_uuid": "activity_38e4781f-547f-4a3c-8513-10c2a399c5df",
    "creation_date": "2026-07-23 10:00:00",
    "update_date": "2026-10-01 23:52:50.403078",
    "extra_metadata": null,
    "current_version": 1,
    "last_modified_by_id": null,
    "last_modified_by_username": null,
    "is_locked": false
  },
