  "activity_2c0cd939-6cc6-4f77-9d1e-290cb4f852a0": {
    "name": "Report critique",
    "activity_type": "TYPE_ASSIGNMENT",
    "activity_sub_type": "SUBTYPE_ASSIGNMENT_ANY",
    "content": {
      "type": "doc",
      "content": [
        {
          "type": "heading",
          "content": [
            {
              "type": "text",
              "text": "Find what is wrong with this report"
            }
          ],
          "attrs": {
            "level": 2
          }
        },
        {
          "type": "paragraph",
          "content": [
            {
              "type": "text",
              "text": "You will be given a one-page summary containing several of the problems in this course: a truncated axis, a metric whose definition changed, an average concealing a skew, and a causal claim resting on a coincidence."
            }
          ]
        },
        {
          "type": "paragraph",
          "content": [
            {
              "type": "text",
              "text": "Identify each one and say what you would ask for to check it. Marked on the problems you find and on the quality of the follow-up question — spotting a flaw without knowing what to ask next is only half the job."
            }
          ]
        }
      ]
    },
    "details": null,
    "published": true,
    "lock_type": "public",
    "id": 99,
    "org_id": 2,
    "course_id": 23,
    "activity_uuid": "activity_2c0cd939-6cc6-4f77-9d1e-290cb4f852a0",
    "creation_date": "2026-07-23 10:00:00",
    "update_date": "2026-10-01 23:52:50.429197",
    "extra_metadata": null,
    "current_version": 1,
    "last_modified_by_id": null,
    "last_modified_by_username": null,
    "is_locked": false
  },
